Problem:
A factory makes bike tires and car tires. Bike tires take 4 minutes on the manufacturing machine and 2 minutes to fill with air. Car tires take 6 minutes on the manufacturing machine and 3.5 minutes to fill with air. The factory can run the manufacturing machine for at most 600 minutes and they have 400 minutes available for filling the tires with air. If the profit per bike tire is $12 and the profit per car tire is $20, how many of each tire should the factory make to maximize profit?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "bike tires made",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "car tires made",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "bike tires made",
     "coef": 12.0
    },
    {
     "var": "car tires made",
     "coef": 20.0
    }
   ]
  },
  "constraints": [
   {
    "name": "manufacturing machine time",
    "terms": [
     {
      "var": "bike tires made",
      "coef": 4.0
     },
     {
      "var": "car tires made",
      "coef": 6.0
     }
    ],
    "sense": "<=",
    "rhs": 600.0
   },
   {
    "name": "air filling time",
    "terms": [
     {
      "var": "bike tires made",
      "coef": 2.0
     },
     {
      "var": "car tires made",
      "coef": 3.5
     }
    ],
    "sense": "<=",
    "rhs": 400.0
   }
  ]
 },
 "facts": {
  "objective": 2000.0,
  "values": {
